package com.treasureverse.backend.purchase;
import com.treasureverse.backend.common.exception.*; import com.treasureverse.backend.common.response.ApiResponse; import jakarta.validation.constraints.NotBlank; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/purchase-posts/{postId}/images") public class PurchasePostImageController { private final PurchasePostRepository posts; private final PurchasePostImageRepository images; public PurchasePostImageController(PurchasePostRepository p,PurchasePostImageRepository i){posts=p;images=i;} record Request(@NotBlank String objectKey){} @PostMapping public ApiResponse<Void> add(@PathVariable Long postId,@RequestBody Request r,@AuthenticationPrincipal String uid){var post=posts.findById(postId).orElseThrow(()->new BusinessException(ErrorCode.RESOURCE_NOT_FOUND)); if(!post.buyerId().equals(Long.valueOf(uid)))throw new BusinessException(ErrorCode.CONFLICT); images.save(new PurchasePostImage(post,r.objectKey(),(int)images.countByPostId(postId)));return ApiResponse.success(null);} }
